export function calculateReadTimeinMinutes(content, readingSpeed = 'medium') {
    // Ensure readingSpeed is a valid string value
    const validSpeed = typeof readingSpeed === 'string' && 
                       ['slow', 'medium', 'fast'].includes(readingSpeed) 
                       ? readingSpeed : 'medium';

    // Handle empty content
    if (!content) {
        return 0;
    }

    const wordCount = content.split(/\s+/).length;
    return Math.round(wordCount / readingSpeeds[validSpeed]);
}
